/// <summary>
/// PaffH 19.11.21
/// display red X if blocked
/// </summary>
/// <returns>container</returns>
[SysClientCacheDataMethodAttribute]
public display container NDXIsBlocked()
{
    return NDXAddressTableHelper::NDXGetBlockedSymbol(this.Blocked);
}

/// <summary>
/// COC of updateCustTable
/// </summary>
protected void updateCustTable()
{   
    CustTable custTable = this.initCustTable();

    if (custTable)
    {
        if(custTable.MainContactWorker != custTable.orig().MainContactWorker || custTable.SalesGroup != custTable.orig().SalesGroup|| custTable.SalesDistrictId != custTable.orig().SalesDistrictId)
        {
            CustTable::NDX_AddSalesUnitHistory(custTable.orig());
        }
    }

    next updateCustTable();
}
